<script setup lang="ts">
import {ref,onMounted} from 'vue';import {api,post,date,fmt} from '../api';import WorkoutChart from '../components/WorkoutChart.vue'
const props=defineProps<{athlete:any}>();const emit=defineEmits(['refresh'])
const workouts=ref<any[]>([]),selected=ref<any>(null),report=ref<any>(null),error=ref(''),busy=ref(false),editing=ref(false)
const form=ref({first_name:props.athlete.first_name,last_name:props.athlete.last_name,age:props.athlete.age,ftp_w:props.athlete.ftp_w})
async function load(){workouts.value=await api(`/athletes/${props.athlete.id}/workouts`)}
async function run(fn:()=>Promise<void>){busy.value=true;error.value='';try{await fn()}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function upload(e:Event){const files=(e.target as HTMLInputElement).files;if(!files?.length)return;await run(async()=>{const data=new FormData();Array.from(files).forEach(f=>data.append('files',f));report.value=await api(`/athletes/${props.athlete.id}/imports`,{method:'POST',body:data});await load()});(e.target as HTMLInputElement).value=''}
async function save(){await run(async()=>{await api(`/athletes/${props.athlete.id}`,{method:'PATCH',body:JSON.stringify({...form.value,ftp_w:form.value.ftp_w||null})});editing.value=false;emit('refresh')})}
async function prepare(){await run(async()=>{await post(`/athletes/${props.athlete.id}/prepare`,{});await load();selected.value=null})}
async function open(id:string){if(selected.value?.id===id){selected.value=null;return}await run(async()=>{selected.value=await api(`/workouts/${id}/series`)})}
onMounted(()=>run(load))
</script>
<template><div class="page-heading"><div><p class="eyebrow">STORICO DI IDENTIFICAZIONE</p><h1>{{athlete.first_name}} {{athlete.last_name}}</h1><p>{{athlete.age}} anni · FTP {{athlete.ftp_w?fmt(athlete.ftp_w)+' W':'non indicata'}}</p></div><div class="actions"><button class="secondary" @click="editing=!editing">Modifica atleta</button><label class="button" :class="{disabled:busy}">+ Importa FIT / ZIP<input type="file" multiple accept=".fit,.zip" @change="upload" :disabled="busy" hidden></label></div></div><form v-if="editing" class="card form-grid" @submit.prevent="save"><label>Nome<input v-model="form.first_name" required></label><label>Cognome<input v-model="form.last_name" required></label><label>Età<input type="number" v-model.number="form.age" required></label><label>FTP · W<input type="number" v-model.number="form.ftp_w"></label><button :disabled="busy">Salva anagrafica</button></form><div class="notice">Regole AR congelate, soglie parametrizzate sulla FTP dell’atleta. Cambiare FTP non modifica esperimenti già salvati. <button class="text-button" @click="prepare" :disabled="busy||!athlete.ftp_w||!workouts.length">Prepara nuova revisione con FTP attuale</button></div><div class="error" v-if="error" role="alert">{{error}}</div><p v-if="busy" class="notice">Elaborazione in corso… Nessun fitting viene avviato.</p><details v-if="report" class="card" open><summary>Esito importazione · {{report.added.length}} nuove attività</summary><p v-for="o in report.outcomes">{{o.file}} — {{o.status}} <span v-if="o.reason">· {{o.reason}}</span></p></details><div v-if="!workouts.length" class="empty"><h2>Importa il primo dataset</h2><p>FIT singoli o uno ZIP contenente FIT, anche in sottocartelle.<br>Puoi aggiungere altre attività in seguito. Originali e duplicati sono tracciati.</p></div><div v-else class="card table-wrap"><table><thead><tr><th>Attività</th><th>Durata</th><th>Utilizzabilità</th><th>Qualità</th><th></th></tr></thead><tbody><template v-for="w in workouts" :key="w.id"><tr :class="{selected:selected?.id===w.id}"><td>{{date(w.start_time)}}<small class="block">{{w.source_name}}</small></td><td>{{fmt(w.duration_s/60,1)}} min</td><td><span class="tag" :class="{good:w.eligible_power}">{{w.eligible_power?'Potenza eleggibile':'Potenza esclusa'}}</span> <span class="tag" :class="{good:w.eligible_hr}">{{w.eligible_hr?'HR eleggibile':'HR esclusa'}}</span><small class="block" v-for="reason in [...w.reasons,...(w.hr_reasons||[])]">{{reason}}</small></td><td>{{w.quality.valid_samples}} / {{w.quality.total_samples}} campioni P<br><small>{{w.quality.missing_hr}} HR mancanti · {{w.quality.non_1s_steps}} gap/passi ≠1 s</small></td><td><button class="secondary" @click="open(w.id)" :disabled="busy" :aria-expanded="selected?.id===w.id" :aria-controls="`workout-${w.id}`">{{selected?.id===w.id?'Chiudi':'Apri'}}</button></td></tr><tr v-if="selected?.id===w.id" :id="`workout-${w.id}`"><td colspan="5"><WorkoutChart :key="selected.id" :series="selected.series" :title="selected.source_name"/><div class="card"><h3>Qualità e provenienza</h3><div class="metric-grid"><div v-for="(v,k) in selected.quality"><small>{{k}}</small><strong>{{v}}</strong></div></div><p class="caption">Prescrizione ricostruita dai lap osservati: non è il piano originale del coach. Nessuna interpolazione o eliminazione automatica delle anomalie.</p><details><summary>Regole e lap</summary><pre>{{JSON.stringify({rules:selected.rules,laps:selected.laps},null,2)}}</pre></details></div></td></tr></template></tbody></table></div></template>
